// 1. 获取 AI 生成的原始文本 (Basic LLM Chain 的输出字段是 text)
const aiRawText = items[0].json.text;

// 2. 容错处理：去掉 AI 可能带的 ```json 等修饰符
const cleanText = aiRawText.replace(/```json/g, "").replace(/```/g, "").trim();

let parsedData;
try {
    // 尝试解析 AI 返回的 JSON
    parsedData = JSON.parse(cleanText);
} catch (e) {
    // 如果 AI 没听话，没返回 JSON，我们手动封装一个，防止流程崩溃
    parsedData = {
        title: "关于关键词的深度解析",
        content: aiRawText
    };
}

// 3. 随机生成 SEO 评分
const seoScore = Math.floor(Math.random() * 15) + 85;

// 4. 返回给下一个节点
return [{
  json: {
    status: 'success',
    data: parsedData, // 这里包含了 Python 想要的 title 和 content
    seo: {
      score: seoScore,
      keyword_density: '2.3%',
      readability_score: 'Good',
      suggestions: [
        '建议在第一段出现关键词',
        '建议添加至少2张图片',
        '建议增加内部链接'
      ]
    },
    timestamp: new Date().toISOString()
  }
}];
